style.marker:
s - a marker is
   resolved in the document, not in the group that points at it, so tone
   would leak from whichever figure happened to render first.

   On a narrow screen the figure scrolls rather than scaling down: SVG
   text shrinks with the viewBox, and a diagram you cannot read is worse
   than one you have to swipe. */
{
}
svg {
  display: block;
  font-family: var(--font-sans), system-ui, -apple-system, sans-serif;
  --fig-c: var(--text-faint);
  --fig-wash: rgba(var(--fg-rgb), 0.04);
}
figcaption {
  margin-top: 14px;
  font-family: var(--font-mono), ui-monospace, monospace;
  font-size: 12px;
  line-height: 1.65;
  letter-spacing: 0.02em;
  color: var(--text-faint);
  text-align: center;
}

/* Tones. Kept in step with the silhouette colours used on the Genesis
   page: Neurons accent, Engrams --p-engram, Effectors accent-3,
   Receptors accent-2. A component wears one colour across the suite. */
.t-neutral  { --fig-c: var(--text-faint);  --fig-wash: rgba(var(--fg-rgb), 0.04); }
.t-accent   { --fig-c: var(--accent);      --fig-wash: rgba(var(--accent-rgb), 0.10); }
.t-accent2  { --fig-c: var(--accent-2);    --fig-wash: rgba(var(--accent2-rgb), 0.10); }
.t-accent3  { --fig-c: var(--accent-3);    --fig-wash: rgba(var(--accent3-rgb), 0.10); }
.t-engram   { --fig-c: var(--p-engram);    --fig-wash: rgba(var(--engram-rgb), 0.10); }
.t-muted    { --fig-c: var(--status-none); --fig-wash: rgba(var(--status-none-rgb), 0.07); }

.fig-box   { fill: var(--fig-wash); stroke: var(--fig-c); stroke-width: 1.2; }
.fig-plain { fill: var(--bg-card);  stroke: var(--border-strong); stroke-width: 1; }
.fig-line  { fill: none; stroke: var(--fig-c); stroke-width: 1.3; }
.fig-hair  { fill: none; stroke: var(--border-strong); stroke-width: 1; }
.fig-dash  { stroke-dasharray: 5 5; }
.fig-fill  { fill: var(--fig-c); stroke: none; }
.fig-hollow{ fill: var(--bg); stroke: var(--fig-c); stroke-width: 1.4; }

.fig-title { fill: var(--text); font-size: 13.5px; font-weight: 600; }
.fig-sub   { fill: var(--text-dim); font-size: 11.5px; }
.fig-tag {
  fill: var(--fig-c);
  font-family: var(--font-mono), ui-monospace, monospace;
  font-size: 11px;
  letter-spacing: 0.04em;
}
.fig-note  { fill: var(--text-faint); font-size: 12px; font-style: italic; }
.fig-strike { stroke: var(--text-faint); stroke-width: 1.2; }

/* ── Figure motion ────────────────────────────────────────────────────
   A Signal on the bus is the one thing worth animating on this site, so
   the only moving part in a figure is a spark travelling a route.

   The route is passed in as custom properties rather than compiled into
   bespoke keyframes per diagram: --x0/--y0 through --x3/--y3 are read
   inside the keyframes, so three generic animations cover every path in
   every figure. Paths here are orthogonal - out of a node, along the bus,
   down into another - which is exactly what a sequence of translates
   draws, and translate needs no transform-origin to behave.

   Each spark also carries its start point as a plain inline transform, so
   when the animation is switched off it rests at the beginning of its
   route instead of collapsing into the top-left corner. */

@keyframes fig-run2 {
  0%   { transform: translate(var(--x0), var(--y0)); opacity: 0; }
  12%  { opacity: 1; }
  88%  { opacity: 1; }
  100% { transform: translate(var(--x1), var(--y1)); opacity: 0; }
}
@keyframes fig-run3 {
  0%   { transform: translate(var(--x0), var(--y0)); opacity: 0; }
  9%   { opacity: 1; }
  50%  { transform: translate(var(--x1), var(--y1)); }
  91%  { opacity: 1; }
  100% { transform: translate(var(--x2), var(--y2)); opacity: 0; }
}
@keyframes fig-run4 {
  0%   { transform: translate(var(--x0), var(--y0)); opacity: 0; }
  7%   { opacity: 1; }
  28%  { transform: translate(var(--x1), var(--y1)); }
  72%  { transform: translate(var(--x2), var(--y2)); }
  93%  { opacity: 1; }
  100% { transform: translate(var(--x3), var(--y3)); opacity: 0; }
}

/* A node acknowledging that something arrived. */
@keyframes fig-halo {
  0%   { transform: scale(0.55); opacity: 0.55; }
  70%  { opacity: 0; }
  100% { transform: scale(2.3); opacity: 0; }
}

/* A dashed edge that is carrying something rather than merely optional. */
@keyframes fig-flow {
  to { stroke-dashoffset: -20; }
}

.fig-spark,
.fig-spark-halo {
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  animation-fill-mode: both;
}
.fig-spark { fill: var(--fig-c); }
.fig-spark-halo { fill: var(--fig-c); fill-opacity: 0.22; }

.fig-halo {
  fill: none;
  stroke: var(--fig-c);
  stroke-width: 1.2;
  transform-box: fill-box;
  transform-origin: center;
  animation-name: fig-halo;
  animation-timing-function: ease-out;
  animation-iteration-count: infinite;
  animation-fill-mode: both;
}

.fig-flow { animation: fig-flow 1.8s linear infinite; }

/* Motion is decoration here - the figure reads perfectly still. */
@media (prefers-reduced-motion: reduce) {
  svg * { animation: none !important; }
  .fig-spark-halo { opacity: 0; }
  .fig-halo { opacity: 0; }
}

/* ── Product miniatures ───────────────────────────────────────────────
   A few figures draw the actual tools at postage-stamp size: Genesis's
   canvas, a terminal, Prism's brain view. They need two type scales the
   rest of the kit does not - chrome (tab strips, window titles) and
   terminal output - and a way to make lines arrive in order. */
.fig-chrome {
  font-family: var(--font-mono), ui-monospace, monospace;
  font-size: 9px;
  letter-spacing: 0.03em;
  fill: var(--text-faint);
}
.fig-chrome.on { fill: var(--fig-c); }
.fig-term {
  font-family: var(--font-mono), ui-monospace, monospace;
  font-size: 9.5px;
  fill: var(--text-dim);
}
.fig-term.dim { fill: var(--text-faint); }
.fig-term.hot { fill: var(--fig-c); }

/* Output arriving a line at a time. Staggered by delay, looping with the
   sparks, so the terminal reads as a program that is still running. */
@keyframes fig-type {
  0%, 4%   { opacity: 0; }
  12%, 100% { opacity: 1; }
}
.fig-type {
  animation-name: fig-type;
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  animation-fill-mode: both;
}

@keyframes fig-blink {
  0%, 49%   { opacity: 1; }
  50%, 100% { opacity: 0; }
}
.fig-caret {
  fill: var(--fig-c);
  animation: fig-blink 1.1s steps(1, end) infinite;
}
